    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;
    private int? updatingId;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private IEnumerable<ShipmentDto> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];

            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var status))
            {
                result = result.Where(s => s.Status == status);
            }

            return result;
        }
    }

    private void ClearFilters()
    {
        searchTerm = string.Empty;
        statusFilter = string.Empty;
    }

    private async Task AdvanceStatus(ShipmentDto shipment)
    {
        var nextStatus = (ShipmentStatus)((int)shipment.Status + 1);
        await UpdateShipmentStatus(shipment, nextStatus);
    }

    private async Task MarkDelivered(ShipmentDto shipment)
    {
        await UpdateShipmentStatus(shipment, ShipmentStatus.Delivered);
    }

    private async Task CancelShipment(ShipmentDto shipment)
    {
        await UpdateShipmentStatus(shipment, ShipmentStatus.Cancelled);
    }

    private async Task UpdateShipmentStatus(ShipmentDto shipment, ShipmentStatus newStatus)
    {
        updatingId = shipment.Id;
        var updated = await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        if (updated is not null)
        {
            var index = shipments!.FindIndex(s => s.Id == shipment.Id);
            if (index >= 0)
                shipments[index] = updated;
        }
        updatingId = null;
    }

