<PageTitle>Dispatcher Dashboard</PageTitle>

<h2 class="mb-4">📋 Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking # or destination..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@if (loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (shipments is null || shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Description</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><a href="/track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                        <td>@s.Description</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <div class="btn-group btn-group-sm">
                                    @if (s.Status < ShipmentStatus.OutForDelivery)
                                    {
                                        <button class="btn btn-outline-primary btn-sm"
                                                @onclick="() => AdvanceStatus(s)"
                                                disabled="@updatingId.HasValue">
                                            Advance ➡️
                                        </button>
                                    }
                                    @if (s.Status == ShipmentStatus.OutForDelivery)
                                    {
                                        <button class="btn btn-success btn-sm"
                                                @onclick="() => MarkDelivered(s)"
                                                disabled="@updatingId.HasValue">
                                            ✅ Delivered
                                        </button>
                                    }
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => CancelShipment(s)"
                                            disabled="@updatingId.HasValue">
                                        Cancel
                                    </button>
                                </div>
                            }
                            else
                            {
                                <span class="text-muted">—</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;
    private int? updatingId;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private IEnumerable<ShipmentDto> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];

            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var status))
            {
                result = result.Where(s => s.Status == status);
            }

            return result;
        }
    }

    private void ClearFilters()
    {
        searchTerm = string.Empty;
        statusFilter = string.Empty;
    }

    private async Task AdvanceStatus(ShipmentDto shipment)
    {
        var nextStatus = (ShipmentStatus)((int)shipment.Status + 1);
        await UpdateShipmentStatus(shipment, nextStatus);
    }

    private async Task MarkDelivered(ShipmentDto shipment)
    {
        await UpdateShipmentStatus(shipment, ShipmentStatus.Delivered);
    }

    private async Task CancelShipment(ShipmentDto shipment)
    {
        await UpdateShipmentStatus(shipment, ShipmentStatus.Cancelled);
    }

    private async Task UpdateShipmentStatus(ShipmentDto shipment, ShipmentStatus newStatus)
    {
        updatingId = shipment.Id;
        var updated = await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        if (updated is not null)
        {
            var index = shipments!.FindIndex(s => s.Id == shipment.Id);
            if (index >= 0)
                shipments[index] = updated;
        }
        updatingId = null;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

