+                        <td>@s.Description</td>
+                        <td>@s.Destination</td>
+                        <td>@s.RecipientName</td>
+                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
+                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
+                        <td>
+                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
+                            {
+                                <div class="btn-group btn-group-sm">
+                                    @if (s.Status < ShipmentStatus.OutForDelivery)
+                                    {
+                                        <button class="btn btn-outline-primary btn-sm"
+                                                @onclick="() => AdvanceStatus(s)"
+                                                disabled="@updatingId.HasValue">
+                                            Advance ➡️
+                                        </button>
+                                    }
+                                    @if (s.Status == ShipmentStatus.OutForDelivery)
+                                    {
+                                        <button class="btn btn-success btn-sm"
+                                                @onclick="() => MarkDelivered(s)"
+                                                disabled="@updatingId.HasValue">
+                                            ✅ Delivered
+                                        </button>
+                                    }
+                                    <button class="btn btn-outline-danger btn-sm"
+                                            @onclick="() => CancelShipment(s)"
+                                            disabled="@updatingId.HasValue">
+                                        Cancel
+                                    </button>
+                                </div>
+                            }
